require_once __DIR__.'/../config/bootstrap.php';require_admin();if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit;}verify_csrf();$id=(int)($_POST['id']??0);$name=trim((string)($_POST['name']??''));$slug=strtolower(trim((string)($_POST['slug']??'')));$sku=trim((string)($_POST['sku']??''));if(!$name||!preg_match('/^[a-z0-9]+(?:-[a-z0-9]+)*$/',$slug)||!$sku){http_response_code(422);exit('Name, valid slug and SKU are required.');}$data=[$name,$slug,$sku,trim((string)($_POST['short_description']??'')),trim((string)($_POST['description']??'')),trim((string)($_POST['fragrance_family']??'')),trim((string)($_POST['concentration']??'')),trim((string)($_POST['gender']??'')),trim((string)($_POST['top_notes']??'')),trim((string)($_POST['heart_notes']??'')),trim((string)($_POST['base_notes']??'')),isset($_POST['is_featured'])?1:0,isset($_POST['is_active'])?1:0];if($id){$sql='UPDATE products SET name=?,slug=?,sku=?,short_description=?,description=?,fragrance_family=?,concentration=?,gender=?,top_notes=?,heart_notes=?,base_notes=?,is_featured=?,is_active=? WHERE id=?';$data[]=$id;}else{$sql='INSERT INTO products(name,slug,sku,short_description,description,fragrance_family,concentration,gender,top_notes,heart_notes,base_notes,is_featured,is_active) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)';}$s=db()->prepare($sql);$s->execute($data);$newId=$id?: (int)db()->lastInsertId();header('Location: /admin/variants.php?product_id='.$newId);exit;